#!/bin/sh
# Generated by Claude Code 2.1.263 (claude-opus-5[1m])
#
# Build the plain C dependencies for arm64-v8a and install them into a
# prefix that the app's CMakeLists can consume with find_package.
#
# These are built out of band rather than as CMake subprojects because they
# find each other through find_package (vorbis needs ogg, libpng needs zlib,
# SDL_ttf needs SDL2), which does not work when they are all pulled into one
# source tree. An install prefix makes those lookups behave normally.
#
# gl4es is handled separately by build-gl4es.sh; SDL2 stays a subproject
# because SDLActivity loads it as a shared library from the APK.

set -e

DEPS_DIR=$(cd "$(dirname "$0")" && pwd)
SRC="$DEPS_DIR/src"
BUILD="$DEPS_DIR/build"
INSTALL="$DEPS_DIR/install"

: "${ANDROID_SDK_ROOT:=$HOME/Android/Sdk}"
: "${ANDROID_NDK_ROOT:=$ANDROID_SDK_ROOT/ndk/27.2.12479018}"

CMAKE="$ANDROID_SDK_ROOT/cmake/3.22.1/bin/cmake"
NINJA="$ANDROID_SDK_ROOT/cmake/3.22.1/bin/ninja"

ABI=arm64-v8a
API=29

# Configure, build and install one dependency.
# Usage: build <name> <extra cmake args...>
build()
{
    name=$1
    shift

    echo "deps: building $name"

    "$CMAKE" -S "$SRC/$name" -B "$BUILD/$name" -G Ninja \
        -DCMAKE_MAKE_PROGRAM="$NINJA" \
        -DCMAKE_TOOLCHAIN_FILE="$ANDROID_NDK_ROOT/build/cmake/android.toolchain.cmake" \
        -DANDROID_ABI="$ABI" \
        -DANDROID_PLATFORM="android-$API" \
        -DCMAKE_BUILD_TYPE=Release \
        -DCMAKE_INSTALL_PREFIX="$INSTALL" \
        -DCMAKE_PREFIX_PATH="$INSTALL" \
        -DCMAKE_FIND_ROOT_PATH="$INSTALL;$ANDROID_NDK_ROOT/toolchains/llvm/prebuilt/linux-x86_64/sysroot" \
        -DBUILD_SHARED_LIBS=OFF \
        "$@" > "$BUILD/$name.log" 2>&1 || {
            echo "deps: $name failed to configure; see $BUILD/$name.log" >&2
            tail -20 "$BUILD/$name.log" >&2
            exit 1
        }

    "$CMAKE" --build "$BUILD/$name" --target install -j "$(nproc)" \
        >> "$BUILD/$name.log" 2>&1 || {
            echo "deps: $name failed to build; see $BUILD/$name.log" >&2
            tail -20 "$BUILD/$name.log" >&2
            exit 1
        }
}

mkdir -p "$BUILD" "$INSTALL"

# Ogg first: vorbis looks for it with find_package.
build ogg

build vorbis

build libpng \
    -DPNG_SHARED=OFF \
    -DPNG_STATIC=ON \
    -DPNG_TESTS=OFF \
    -DPNG_TOOLS=OFF \
    -DPNG_FRAMEWORK=OFF

build libjpeg \
    -DENABLE_SHARED=OFF \
    -DENABLE_STATIC=ON \
    -DWITH_TURBOJPEG=OFF

build freetype \
    -DFT_DISABLE_HARFBUZZ=ON \
    -DFT_DISABLE_BROTLI=ON \
    -DFT_DISABLE_BZIP2=ON \
    -DFT_DISABLE_PNG=ON \
    -DFT_DISABLE_ZLIB=ON

echo "deps: installed into $INSTALL"
